#include <vector>
#include <algorithm>

int main() {
    std::vector<int> v = {10, 20, 30};

    // O(1) Random Access
    int value = v[1]; 

    // High performance iteration due to contiguity
    std::for_each(v.begin(), v.end(), [](int& x) {
        x *= 2; // Cache friendly operation
    });

    // O(N) operation: insertion in the middle
    v.insert(v.begin() + 1, 15); 

    // Amortized O(1) operation
    v.push_back(40);
}
